import functools

def memoize_lru(maxsize=128):
    def decorator(func):
        cache = {}
        order = []

        @functools.wraps(func)
        def wrapper(*args):
            if args in cache:
                return cache[args]
            result = func(*args)
            cache[args] = result
            order.append(args)
            if len(cache) > maxsize:
                del cache[order.pop(0)]
            return result

        def cache_clear():
            cache.clear()
            order.clear()

        wrapper.cache_clear = cache_clear
        wrapper.cache_info = lambda: {'size': len(cache), 'maxsize': maxsize}
        return wrapper
    return decorator

@memoize_lru(maxsize=10)
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)

