import time

def rate_limit(n, period):
    def decorator(func):
        calls = []

        def wrapper(*args, **kwargs):
            now = time.monotonic()
            calls[:] = [t for t in calls if now - t < period]
            if len(calls) >= n:
                raise RuntimeError('rate limit exceeded')
            calls.append(now)
            return func(*args, **kwargs)
        return wrapper
    return decorator

