import functools, time

def make_cache(ttl=60.0):
    def decorator(func):
        store = {}

        @functools.wraps(func)
        def wrapper(*args):
            entry = store.get(args)
            if entry and time.monotonic() - entry[1] < ttl:
                return entry[0]
            result = func(*args)
            store[args] = (result, time.monotonic())
            return result
        return wrapper
    return decorator

